function znormalizujEmail(email) {
  return email.trim().toLowerCase();
}

console.log(znormalizujEmail("  Ola.NOWAK@Firma.COM  "));
// "ola.nowak@firma.com"

function wyodrebnijDomeny(email) {
  const indeksMalpy = email.indexOf("@");
  return email.slice(indeksMalpy + 1);
}

console.log(wyodrebnijDomeny("user@example.com")); // "example.com"

function czyZawieraSlowo(zdanie, slowo) {
  return zdanie.toLowerCase().includes(slowo.toLowerCase());
}

console.log(czyZawieraSlowo("Kocham programowanie", "PROGRAMOWANIE")); // true

const email = "jan.kowalski@firma.pl";
const [uzytkownik, domena] = email.split("@");
console.log(uzytkownik); // "jan.kowalski"
console.log(domena);     // "firma.pl"

function ukryjNumerKarty(numer) {
  return "*".repeat(12) + numer.slice(-4);
}

console.log(ukryjNumerKarty("1234567890123456")); // "************3456"

const zdanie = "  Za duzo   spacji   miedzy slowami  ";
const fragmenty = zdanie.trim().split(" ");
console.log(fragmenty.length); // wiecej niz 5 - wielokrotne spacje tworza puste elementy ''

const data = "2024-01-15";
const [rok, miesiac, dzien] = data.split("-");
console.log(`Dzien: ${dzien}, Miesiac: ${miesiac}, Rok: ${rok}`);
// Dzien: 15, Miesiac: 01, Rok: 2024

function skrocTekst(tekst, maxDlugosc) {
  if (tekst.length > maxDlugosc) {
    return tekst.slice(0, maxDlugosc) + "...";
  }
  return tekst;
}

console.log(skrocTekst("To jest bardzo dlugi tekst", 10)); // "To jest bar..."
console.log(skrocTekst("Krotki", 10)); // "Krotki"

function zliczWystapienia(tekst, fragment) {
  return tekst.split(fragment).length - 1;
}

console.log(zliczWystapienia("banan", "an")); // 2

const kod = "produkt_ID_12345";
const czesci = kod.split("_");
console.log(czesci.pop()); // "12345"

function formatujCzas(minuty, sekundy) {
  const mm = String(minuty).padStart(2, "0");
  const ss = String(sekundy).padStart(2, "0");
  return `${mm}:${ss}`;
}

console.log(formatujCzas(5, 3)); // "05:03"

